  CPU_DATA = TRICORE{
    CPU_CLOCK = 200.0;
    ...
  };

  COUNTER SystemTimer {
    MINCYCLE = 1;
    MAXALLOWEDVALUE = 2147483647;
    TICKSPERBASE = 1;
    TYPE = HARDWARE {
      DEVICE = "STM_SR0";
      SYSTEM_TIMER = TRUE;
      PRIORITY = 1;
    };
    SECONDSPERTICK = 0.001;
  };

